/*
 * rbtree.h -- CS 313 P4: red-black tree (CLRS 4th edition, chapter 13).
 *
 * DO NOT EDIT THIS FILE. The autograder uses its own copy.
 *
 * The tree uses one sentinel node, T->nil, exactly as in CLRS.
 * Every "NIL" leaf and the root's parent are T->nil. T->nil is black.
 * An empty tree has T->root == T->nil.
 *
 * Duplicate keys are allowed. As in CLRS, a key equal to a node's key
 * goes into that node's RIGHT subtree.
 */
#ifndef RBTREE_H
#define RBTREE_H

#include <stdbool.h>
#include <stddef.h>

typedef enum { RB_RED = 0, RB_BLACK = 1 } rb_color;

typedef struct rb_node {
    int key;
    rb_color color;
    struct rb_node *left;
    struct rb_node *right;
    struct rb_node *p;          /* parent; T->nil for the root */
} rb_node;

typedef struct {
    rb_node *root;              /* T->nil when the tree is empty */
    rb_node *nil;               /* the single sentinel node */
    size_t size;                /* number of keys in the tree */
    unsigned long version;      /* goes up by 1 with every insert and delete */
} rb_tree;

/* ---------- Provided (working) ---------- */

rb_tree *rb_create(void);                          /* new empty tree, or NULL if out of memory */
void     rb_destroy(rb_tree *T);                   /* free every node, the sentinel, and T */
size_t   rb_size(const rb_tree *T);                /* number of keys */
rb_node *rb_search(const rb_tree *T, int key);     /* node with key, or T->nil if absent */
bool     rb_contains(const rb_tree *T, int key);   /* true if key is in the tree */
bool     rb_minimum(const rb_tree *T, int *out);   /* smallest key into *out; false if empty */
bool     rb_insert(rb_tree *T, int key);           /* BST insert, then rb_insert_fixup; false only if out of memory */
bool     rb_bst_insert(rb_tree *T, int key);       /* plain BST insert, NO fixup (for testing rotations) */
bool     rb_delete(rb_tree *T, int key);           /* CLRS RB-DELETE; false (tree unchanged) if key absent */
size_t   rb_preorder(const rb_tree *T, int keys[], rb_color colors[], size_t cap);
                                                   /* write the first cap nodes in preorder into keys[] and
                                                      colors[] (either may be NULL); returns the number of
                                                      nodes, which is more than cap if the arrays were too small */
int      rb_height(const rb_tree *T);              /* edges on longest root-to-leaf path; -1 if empty */
bool     rb_is_valid(const rb_tree *T, const char **why);
                                                   /* check BST order, parent links, size, and all
                                                      red-black properties; on failure sets *why
                                                      (if why != NULL) to a short reason */
void     rb_print(const rb_tree *T);               /* draw the tree sideways on stdout, for debugging;
                                                      marks any node whose parent pointer is wrong */

/* ---------- You implement these four, and the iterator below (in rbtree.c) ---------- */

/* CLRS LEFT-ROTATE. Returns false and changes nothing if x == T->nil
 * or x->right == T->nil. Colors are not changed. */
bool rb_left_rotate(rb_tree *T, rb_node *x);

/* CLRS RIGHT-ROTATE (mirror image). Returns false and changes nothing if
 * x == T->nil or x->left == T->nil. */
bool rb_right_rotate(rb_tree *T, rb_node *x);

/* CLRS RB-INSERT-FIXUP. Called by rb_insert after z (red) is linked in. */
void rb_insert_fixup(rb_tree *T, rb_node *z);

/* CLRS RB-DELETE-FIXUP. Called by rb_delete when a black node was removed
 * or moved. x may be T->nil; in that case T->nil->p has been set. */
void rb_delete_fixup(rb_tree *T, rb_node *x);

/* ---------- Inorder iterator (you implement these three too) ----------
 *
 * An iterator hands out the keys in sorted order, one key per call. The
 * caller runs the loop and may stop early, and no array is needed:
 *
 *     rb_iter it = rb_iter_first(T);
 *     int key;
 *     while (rb_iter_next(&it, &key))
 *         printf("%d\n", key);
 *
 * An insert or a delete can free or move the node an iterator points to.
 * So an iterator records the tree's version when it is made, and once the
 * tree has changed, rb_iter_next returns false without reading that node.
 * Like feof and ferror after fgetc, rb_iter_changed tells the caller
 * whether false meant "no keys left" or "the tree changed".
 */
typedef struct {
    const rb_tree *T;
    const rb_node *next;        /* the node whose key comes next; T->nil when none are left */
    unsigned long version;      /* T->version when the iterator was made */
} rb_iter;

/* Provided: true if the tree has been changed since the iterator was made. */
bool rb_iter_changed(const rb_iter *it);

/* An iterator that starts at the smallest key. */
rb_iter rb_iter_first(const rb_tree *T);

/* An iterator that starts at the first key >= lo, in sorted order. With
 * duplicates, that is the first copy. Walk down from the root once. */
rb_iter rb_iter_from(const rb_tree *T, int lo);

/* If the tree has changed (rb_iter_changed), return false and leave *key
 * alone, without reading it->next. Otherwise, if a key is left, set *key
 * to it, advance, and return true; if none is left, return false and
 * leave *key alone. Find the next node as CLRS
 * TREE-SUCCESSOR does, with the parent pointers. */
bool rb_iter_next(rb_iter *it, int *key);

#endif
